import { VercelRequest, VercelResponse } from '@vercel/node';
import { db, cors, verifyAuth, FieldValue } from '../_lib/common';
import { StravaApi } from '../_lib/strava-api';
import { SyncService } from '../_lib/sync-service';

const STRAVA_CLIENT_ID = process.env.STRAVA_CLIENT_ID;
const STRAVA_CLIENT_SECRET = process.env.STRAVA_CLIENT_SECRET;
const STRAVA_REDIRECT_URI = process.env.STRAVA_REDIRECT_URI;
const STRAVA_VERIFY_TOKEN = process.env.STRAVA_VERIFY_TOKEN || process.env.STRAVA_WEBHOOK_SECRET;

export default async function handler(req: any, res: any) {
  if (cors(req, res)) return;

  const { method, query } = req;
  const action = (query.stravaAction as string) || (query.action as string) || 'status';

  try {
    // 1. Webhook Validation (Public GET from Strava)
    if (method === 'GET' && query['hub.mode'] === 'subscribe') {
      return handleWebhookValidation(req, res);
    }

    // 2. Webhook Event Handling (Public POST from Strava)
    if (method === 'POST' && !query.action) {
      return handleWebhookEvent(req, res);
    }

    // 3. User-Initiated Actions (Requires Auth)
    const auth = await verifyAuth(req);
    
    // Auth requirement (except callback which uses state=userId)
    if (!auth && action !== 'callback') {
      return res.status(401).json({ error: 'Authentication required' });
    }

    const userId = auth?.uid || (query.state as string);
    if (!userId) {
      return res.status(400).json({ error: 'User ID missing' });
    }

    const strava = new StravaApi(userId);

    switch (action) {
      case 'auth':
        return await initiateAuth(res, userId);
      case 'callback':
        return await handleCallback(req, res, strava);
      case 'status':
        return await getStatus(res, strava);
      case 'sync':
        return await manualSync(res, strava);
      case 'disconnect':
        await strava.deleteConnection();
        return res.json({ success: true });
      default:
        return res.status(400).json({ error: 'Invalid action' });
    }
  } catch (error: any) {
    console.error(`[Strava API Error] Action: ${action}`, error);
    return res.status(500).json({ error: error.message || 'Internal Server Error' });
  }
}

async function initiateAuth(res: VercelResponse, userId: string) {
  const scope = 'read,activity:read_all';
  const url = `https://www.strava.com/oauth/authorize?client_id=${STRAVA_CLIENT_ID}&redirect_uri=${encodeURIComponent(STRAVA_REDIRECT_URI!)}&response_type=code&scope=${scope}&state=${userId}`;
  return res.json({ url });
}

async function handleCallback(req: VercelRequest, res: VercelResponse, strava: StravaApi) {
  const { code } = req.query;
  if (!code) return res.status(400).json({ error: 'Code missing' });

  const response = await fetch('https://www.strava.com/oauth/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      client_id: STRAVA_CLIENT_ID,
      client_secret: STRAVA_CLIENT_SECRET,
      code,
      grant_type: 'authorization_code'
    })
  });

  if (!response.ok) {
    const err = await response.text();
    throw new Error(`Strava token exchange failed: ${err}`);
  }

  const data = await response.json();
  await strava.saveConnection(data);

  // Trigger initial historical import (async)
  manualSyncInternal(strava).catch(console.error);

  const appUrl = (process.env.APP_URL || '').replace(/\/$/, '');
  return res.redirect(`${appUrl}/profile?strava=connected`);
}

async function getStatus(res: VercelResponse, strava: StravaApi) {
  const conn = await strava.getConnection();
  return res.json({
    connected: !!conn,
    athleteId: conn?.athleteId || null,
    lastSync: conn?.lastSyncAt || null
  });
}

async function manualSync(res: VercelResponse, strava: StravaApi) {
  const result = await manualSyncInternal(strava);
  return res.json(result);
}

async function manualSyncInternal(strava: StravaApi) {
  // Fetch last 60 days for a strong start
  const after = Math.floor(Date.now() / 1000) - (60 * 24 * 60 * 60);
  const activities = await strava.fetchActivities(after);
  
  let syncCount = 0;
  for (const act of activities) {
    if (await SyncService.processStravaActivity((strava as any).userId, act)) {
      syncCount++;
    }
  }

  const userId = (strava as any).userId;
  await db.collection('strava_connections').doc(userId).update({
    lastSyncAt: new Date().toISOString()
  });

  return { success: true, syncCount };
}

function handleWebhookValidation(req: VercelRequest, res: VercelResponse) {
  const verifyToken = req.query['hub.verify_token'];
  const challenge = req.query['hub.challenge'];
  
  if (verifyToken === STRAVA_VERIFY_TOKEN) {
    return res.status(200).json({ 'hub.challenge': challenge });
  }
  return res.status(403).json({ error: 'Webhook verification failed' });
}

async function handleWebhookEvent(req: VercelRequest, res: VercelResponse) {
  const event = req.body;
  console.log('[Strava Webhook] Event:', event);

  // We only care about new activities
  if (event.object_type === 'activity' && event.aspect_type === 'create') {
    const athleteId = event.owner_id.toString();
    const athleteSnap = await db.collection('strava_athletes').doc(athleteId).get();
    
    if (athleteSnap.exists) {
      const userId = athleteSnap.data()?.userId;
      if (userId) {
        const strava = new StravaApi(userId);
        try {
          const activity = await strava.fetchActivity(event.object_id);
          await SyncService.processStravaActivity(userId, activity);
        } catch (e) {
          console.error(`[Strava Webhook] Failed to process activity ${event.object_id}:`, e);
        }
      }
    }
  }

  return res.status(200).json({ success: true });
}
