import { VercelRequest, VercelResponse } from '@vercel/node';
import { 
  db,
  cors,
  verifyAuth,
  FieldValue,
  FieldPath,
  doc,
  getDoc,
  setDoc,
  collection,
  query as webQuery,
  where as webWhere,
  orderBy as webOrderBy,
  limit as webLimit,
  getDocs,
  getCountFromServer,
  serverTimestamp,
  documentId
} from '../_lib/common';
import { startOfMonth, endOfMonth, startOfWeek, endOfWeek, isWithinInterval } from 'date-fns';
import NodeCache from 'node-cache';

const cache = new NodeCache({ stdTTL: 300 }); // Increase to 5 mins

export default async function handler(req: VercelRequest, res: VercelResponse) {
  if (cors(req, res)) return;

  const { method, query: reqQuery } = req;
  const action = (reqQuery.action as string) || 'me';

  try {
    const auth = await verifyAuth(req);
    
    // Auth requirement: Block sensitive actions if not authenticated
    const sensitiveActions = ['me', 'add', 'history'];
    if (sensitiveActions.includes(action) && !auth) {
      return res.status(401).json({ error: 'Autenticação necessária.' });
    }

    // Security: for 'me' and 'history' of a specific user, ensure it matches auth
    const queryUserId = req.query.userId as string;
    const bodyUserId = req.body?.userId as string;
    const targetUserId = queryUserId || bodyUserId || (action === 'me' ? auth?.uid : null);
    
    // If it's 'me' and no userId provided, use the auth uid
    if (action === 'me' && !queryUserId && !bodyUserId && auth) {
      req.query.userId = auth.uid;
    }

    if (auth && targetUserId && targetUserId !== auth.uid) {
       console.warn(`[Running API] User ${auth.uid} attempting to access data for ${targetUserId}`);
       // Block cross-user access unless it's a public action (like ranking)
       if (action === 'me' || action === 'add' || action === 'history') {
         return res.status(403).json({ error: 'Acesso negado. Você só pode acessar seus próprios dados.' });
       }
    }

    // Use the single exported db instance
    if (!db) {
      return res.status(500).json({ 
        error: 'Falha na inicialização do banco de dados.',
        details: 'Admin SDK não inicializado.'
      });
    }

    return await runAction(action, req, res);
  } catch (error: any) {
    const errorMsg = error.message || '';
    const isQuotaError = errorMsg.includes('RESOURCE_EXHAUSTED') || errorMsg.includes('Quota limit exceeded');
    
    console.error(`[Running API] Operation "${action}" failed. Error: ${errorMsg}`);
    
    if (isQuotaError) {
      return res.status(429).json({
        error: 'Servidor sob alta carga. Tente novamente em alguns instantes.',
        code: 'QUOTA_EXHAUSTED',
        fallback: true
      });
    }

    return res.status(500).json({ 
      error: `Erro ao processar ${action}: ${errorMsg}`,
      details: error.stack
    });
  }
}

async function runAction(action: string, req: VercelRequest, res: VercelResponse) {
  switch (action) {
    case 'me':
      return await getUserStats(req, res);
    case 'add':
      return await addRun(req, res);
    case 'ranking':
      return await getRanking(req, res);
    case 'history':
      return await getHistory(req, res);
    default:
      return res.status(400).json({ error: 'Invalid action' });
  }
}

async function getUserStats(req: VercelRequest, res: VercelResponse) {
  const userId = req.query.userId as string;
  if (!userId) return res.status(400).json({ error: 'User ID required' });

  const cacheKey = `user_stats_${userId}`;
  const cached = cache.get(cacheKey);
  if (cached) return res.json(cached);

  try {
    const snap = await db.collection('running_stats').doc(userId).get();
    
    if (!snap.exists) {
      const defaultStats = {
        userId,
        best_run_km_month: 0,
        best_run_km_week: 0,
        last_run_date: new Date().toISOString(),
        is_paid_running: false
      };
      cache.set(cacheKey, defaultStats, 600); // 10 mins cache
      return res.json(defaultStats);
    }

    const data = snap.data();
    const now = new Date();
    const lastRun = data?.last_run_date ? new Date(data.last_run_date) : null;

    let best_run_km_month = data?.best_run_km_month || 0;
    let best_run_km_week = data?.best_run_km_week || 0;

    if (lastRun) {
      if (!isWithinInterval(lastRun, { start: startOfMonth(now), end: endOfMonth(now) })) {
        best_run_km_month = 0;
      }
      if (!isWithinInterval(lastRun, { start: startOfWeek(now, { weekStartsOn: 1 }), end: endOfWeek(now, { weekStartsOn: 1 }) })) {
        best_run_km_week = 0;
      }
    }

    const result = { ...data, best_run_km_month, best_run_km_week };
    cache.set(cacheKey, result, 600); // 10 mins cache
    return res.json(result);
  } catch (err: any) {
    const isQuotaError = err.message?.includes('RESOURCE_EXHAUSTED') || err.message?.includes('Quota limit exceeded');
    if (isQuotaError) {
       console.warn(`[Running API] Quota hit for getUserStats(${userId}), returning error response with fallback hint`);
       return res.status(429).json({
         error: 'Servidor sob alta carga. Tente novamente em instantes.',
         code: 'QUOTA_EXHAUSTED',
         fallback: true,
         userId // Send back ID so UI can at least identify the scope
       });
    }
    throw err;
  }
}

async function addRun(req: VercelRequest, res: VercelResponse) {
  const { userId, km, timeSeconds, pace, calories, elevationGain, steps, trajectory, date, session } = req.body;
  if (!userId || km === undefined) return res.status(400).json({ error: 'Missing parameters' });

  try {
    const snap = await db.collection('running_stats').doc(userId).get();
    
    const now = new Date();
    const nowIso = now.toISOString();

    let data = snap.exists ? snap.data() : {
      userId,
      best_run_km_month: 0,
      best_run_km_week: 0,
      last_run_date: nowIso,
      is_paid_running: false
    };

    const lastRun = data?.last_run_date ? new Date(data.last_run_date) : null;
    let currentMonthBest = data?.best_run_km_month || 0;
    let currentWeekBest = data?.best_run_km_week || 0;

    if (lastRun) {
      if (!isWithinInterval(lastRun, { start: startOfMonth(now), end: endOfMonth(now) })) currentMonthBest = 0;
      if (!isWithinInterval(lastRun, { start: startOfWeek(now, { weekStartsOn: 1 }), end: endOfWeek(now, { weekStartsOn: 1 }) })) currentWeekBest = 0;
    }

    const currentKm = parseFloat(km);
    if (currentKm > currentMonthBest) currentMonthBest = currentKm;
    if (currentKm > currentWeekBest) currentWeekBest = currentKm;

    const lastRunStats = {
      km: currentKm,
      timeSeconds: timeSeconds || 0,
      pace: pace || "0'00\"/km",
      calories: calories || 0,
      elevationGain: elevationGain || 0,
      steps: steps || 0,
      trajectory: trajectory || [],
      date: date || nowIso
    };

    const updatedData = {
      ...data,
      best_run_km_month: currentMonthBest,
      best_run_km_week: currentWeekBest,
      last_run_date: nowIso,
      last_run_stats: lastRunStats
    };

    let sessionId = null;
    if (session) {
      const sessionRef = db.collection('run_sessions').doc();
      sessionId = sessionRef.id;
      await sessionRef.set({
          ...session,
          id: sessionId,
          userId,
          createdAt: FieldValue.serverTimestamp()
      });
    }

    await db.collection('running_stats').doc(userId).set(updatedData, { merge: true });
    
    // Update User score and totalActiveDays in the users collection
    const userRef = db.collection('users').doc(userId);
    
    // Calculate week
    const getWeekNumber = (date: Date) => {
      const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
      const dayNum = d.getUTCDay() || 7;
      d.setUTCDate(d.getUTCDate() + 4 - dayNum);
      const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
      return Math.ceil((((d.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
    };

    const currentWeekInfo = getWeekNumber(now);
    const weekId = `${now.getFullYear()}-W${currentWeekInfo}`;
    const todayISO = nowIso.split('T')[0];
    const weeklyStatsRef = db.collection('users').doc(userId).collection('weeklyStats').doc(weekId);

    let isScoringEligible = false;
    let nonScoringReason: string | null = null;
    let finalXpAwarded = 0;

    // PRESENÇA VERIFICADA Layer (Biometrics & Adaptive Risk Trigger) for Runs
    let trustScore = 100;
    try {
      const userRefSnap = await db.collection('users').doc(userId).get();
      const userData = userRefSnap.exists ? (userRefSnap.data() || {}) : {};
      
      const trustProfileSnap = await db.collection('user_trust_profiles').doc(userId).get();
      if (trustProfileSnap.exists) {
        trustScore = trustProfileSnap.data()?.trustScore ?? 100;
      } else if (userData.createdAt) {
        const ageMs = Date.now() - new Date(userData.createdAt).getTime();
        const ageDays = ageMs / (1000 * 60 * 60 * 24);
        trustScore = ageDays > 30 ? 95 : 70;
      } else {
        trustScore = 70;
      }
    } catch (_) {}

    let riskAcc = 10;
    const isMockLoc = req.body.isMockLocation || false;
    const isEmu = req.body.isEmulator || false;
    const isRoot = req.body.isRooted || false;
    const isDev = req.body.isDeveloperMode || false;
    const hasOscillation = req.body.hasSensorOscillation ?? true;
    const sensStatus = req.body.sensorStatus || 'unavailable';

    if (isEmu || isDev) riskAcc += 25;
    if (isMockLoc || isRoot) riskAcc += 45;
    if (sensStatus === 'unavailable' || !hasOscillation) riskAcc += 15;
    
    // Biomechanical Speed Check
    const calculatedSpeedKmh = currentKm / ((timeSeconds || 3600) / 3600);
    if (calculatedSpeedKmh > 22.0) riskAcc += 35; // faster than marathon world record pace
    else if (calculatedSpeedKmh > 16.0) riskAcc += 15;

    const presenceRiskScore = Math.min(100, Math.max(0, riskAcc));

    let presenceCheckRequired = false;
    if (presenceRiskScore >= 75) {
      presenceCheckRequired = true;
    } else {
      let triggerProbability = 0.10; // normal mode 10% standard chance
      
      if (trustScore >= 90) {
        triggerProbability = 0.05; // trusted history: lower checks (5%)
      } else if (trustScore < 70) {
        triggerProbability = 0.30; // newer or low trust history: higher checks (30%)
      }
      
      if (presenceRiskScore >= 40) {
        triggerProbability = Math.max(triggerProbability, 0.40); // suspicious telemetry: higher checks (40%)
      }

      presenceCheckRequired = (Math.random() < triggerProbability);
    }

    if (presenceCheckRequired) {
      const dbCollection = db.collection('pending_presence_checks');
      const presenceCheckId = dbCollection.doc().id;
      const nowTime = new Date();
      const expiredAt = new Date(nowTime.getTime() + 15 * 60 * 1000).toISOString();

      const GESTURES = [
        "pisque os olhos repetidamente",
        "dê um sorriso natural para a câmera",
        "vire a cabeça levemente para a esquerda",
        "vire a cabeça levemente para a direita",
        "levante uma das mãos à altura do ombro",
        "olhe diretamente para cima e depois para a câmera"
      ];
      const livenessPrompt = GESTURES[Math.floor(Math.random() * GESTURES.length)];

      await dbCollection.doc(presenceCheckId).set({
        id: presenceCheckId,
        userId: userId,
        type: 'running',
        livenessPrompt,
        riskScore: presenceRiskScore,
        createdAt: nowTime.toISOString(),
        expiredAt,
        workoutPayload: req.body,
        status: 'pending'
      });

      return res.json({
        success: true, // indicate endpoint parsing success
        status: "presence_check_required",
        presenceCheckRequired: true,
        presenceCheckId,
        livenessPrompt,
        userMessage: "Para finalizar sua corrida e computar seus pontos, conclua a confirmação rápida de presença."
      });
    }

    await db.runTransaction(async (transaction: any) => {
      const userSnap = await transaction.get(userRef);
      if (!userSnap.exists) return;
      const userData = userSnap.data();

      let xpAwarded = (userData.isSubscribed || true) ? (20 + Math.floor(currentKm * 5)) : 0; // Open for testing

      const weeklyStatsSnap = await transaction.get(weeklyStatsRef);
      let weeklyStatsData = weeklyStatsSnap.exists ? weeklyStatsSnap.data() : {
        weekId,
        scoredDays: [],
        totalScoredDays: 0,
        totalPoints: 0
      };

      const scoredDays = weeklyStatsData.scoredDays || [];
      const isDayAlreadyScored = scoredDays.includes(todayISO);

      if (xpAwarded > 0) {
        if (isDayAlreadyScored) {
          isScoringEligible = true;
          finalXpAwarded = xpAwarded;
        } else if (scoredDays.length < 5) {
          isScoringEligible = true;
          finalXpAwarded = xpAwarded;
          scoredDays.push(todayISO);
          weeklyStatsData.scoredDays = scoredDays;
          weeklyStatsData.totalScoredDays = scoredDays.length;
        } else {
          isScoringEligible = false;
          nonScoringReason = "WEEKLY_SCORING_LIMIT_REACHED";
          finalXpAwarded = 0;
        }
      } else {
        isScoringEligible = true;
      }

      const userUpdates: any = {
        updatedAt: FieldValue.serverTimestamp()
      };

      if (userData.isSubscribed || true) { // Open for testing
        userUpdates.score = (userData.score || 0) + finalXpAwarded;
        userUpdates.lastCheckIn = nowIso;

        // Check for totalActiveDays increment
        const lastCheckInDay = userData.lastCheckIn ? userData.lastCheckIn.split('T')[0] : '';
        if (todayISO !== lastCheckInDay) {
          userUpdates.totalActiveDays = (userData.totalActiveDays || 0) + 1;
        }
      }

      if (finalXpAwarded > 0) {
        weeklyStatsData.totalPoints = (weeklyStatsData.totalPoints || 0) + finalXpAwarded;
        weeklyStatsData.updatedAt = FieldValue.serverTimestamp();
        transaction.set(weeklyStatsRef, weeklyStatsData);
      }

      transaction.update(userRef, userUpdates);
    });

    cache.flushAll();

    const isWeeklyLimit = !isScoringEligible && nonScoringReason === "WEEKLY_SCORING_LIMIT_REACHED";
    const userMsg = isWeeklyLimit
      ? "Treino registrado com sucesso, mas você já atingiu seus 5 dias pontuáveis da semana."
      : "Corrida validada com sucesso! Seus pontos foram adicionados.";

    return res.json({ 
      ...updatedData, 
      sessionId,
      isScoringEligible,
      nonScoringReason,
      pointsEarned: finalXpAwarded,
      success: !isWeeklyLimit,
      status: isWeeklyLimit ? "not_validated" : "approved",
      reasonCode: isWeeklyLimit ? "WEEKLY_LIMIT_REACHED" : null,
      userMessage: userMsg,
      canRetry: false,
      pointsAwarded: finalXpAwarded,
      message: userMsg
    });
  } catch (err: any) {
    const isQuotaError = err.message?.includes('RESOURCE_EXHAUSTED') || err.message?.includes('Quota limit exceeded');
    if (isQuotaError) {
      return res.status(429).json({
        error: 'Servidor ocupado. Tente novamente em instantes.',
        code: 'QUOTA_EXHAUSTED_WRITE'
      });
    }
    throw err;
  }
}

async function getRanking(req: VercelRequest, res: VercelResponse) {
  const period = req.query.period as 'month' | 'week';
  const mode = (req.query.mode as 'official' | 'demo') || 'official';
  const userId = req.query.userId as string;

  if (!period) return res.status(400).json({ error: 'Period required' });

  const cacheKey = `ranking_${period}_${mode}`; // Use same ranking cache for everyone to save quota
  const cachedData = cache.get(cacheKey);
  if (cachedData) return res.json(cachedData);

  try {
    const field = period === 'month' ? 'best_run_km_month' : 'best_run_km_week';
    const now = new Date();
    const start = period === 'month' ? startOfMonth(now) : startOfWeek(now, { weekStartsOn: 1 });
    const isPaidFilter = mode === 'official';

    const querySnap = await db.collection('running_stats')
      .where('is_paid_running', '==', isPaidFilter)
      .where(field, '>', 0)
      .where('last_run_date', '>=', start.toISOString())
      .orderBy(field, 'desc')
      .limit(10)
      .get();

    const runnerIds = querySnap.docs.map((snap: any) => snap.data().userId);
    const runnerMap = new Map();
    if (runnerIds.length > 0) {
      // Chunk users fetch if needed, but here it's only 10 users
      const usersSnap = await db.collection('users').where(FieldPath.documentId(), 'in', runnerIds).get();
      usersSnap.forEach((d: any) => runnerMap.set(d.id, d.data()));
    }

    const ranking = querySnap.docs.map((snap: any) => {
      const data = snap.data();
      const userData = runnerMap.get(data.userId);
      return {
        userId: data.userId,
        displayName: userData?.displayName || 'Velocista Anônimo',
        photoURL: userData?.photoURL || null,
        km: data[field],
        is_paid_running: data.is_paid_running
      };
    });

    // Optimize: Get pool and count from aggregated stats if possible
    let totalCount = 0;
    let totalPool = 0;
    
    try {
      const statsSnap = await db.collection('system_stats').doc('global').get();
      if (statsSnap.exists) {
        const stats = statsSnap.data();
        totalCount = stats?.activeUserCount || 0;
        totalPool = stats?.pools?.poolValues?.national || (totalCount * 19.90 * 0.5);
      }
    } catch (e) {
      console.warn('[Ranking API] Failed to fetch system stats');
    }

    const result = { ranking, totalPool };
    cache.set(cacheKey, result, 900); // 15 mins cache for ranking
    return res.json(result);
  } catch (err: any) {
    const isQuotaError = err.message?.includes('RESOURCE_EXHAUSTED') || err.message?.includes('Quota limit exceeded');
    if (isQuotaError) {
       return res.status(429).json({ error: 'Ranking temporariamente indisponível.', code: 'QUOTA_EXHAUSTED' });
    }
    throw err;
  }
}

async function getHistory(req: VercelRequest, res: VercelResponse) {
  const userId = req.query.userId as string;
  if (!userId) return res.status(400).json({ error: 'User ID required' });

  const snap = await db.collection('run_sessions')
    .where('userId', '==', userId)
    .orderBy('createdAt', 'desc')
    .limit(10)
    .get();

  const history = snap.docs.map((doc: any) => ({
    id: doc.id,
    ...doc.data()
  }));

  return res.json({ history });
}
