import { VercelRequest, VercelResponse } from '@vercel/node';
import { db, cors, verifyAuth, FieldValue } from '../_lib/common';
import { GoogleGenAI, Type } from "@google/genai";
import crypto from 'crypto';

// Instantiate Gemini server-side using modern @google/genai SDK
const ai = new GoogleGenAI({
  apiKey: process.env.GEMINI_API_KEY || '',
  httpOptions: {
    headers: {
      'User-Agent': 'aistudio-build',
    }
  }
});

export default async function handler(req: VercelRequest, res: VercelResponse) {
  if (cors(req, res)) return;

  const auth = await verifyAuth(req);
  if (!auth) return res.status(401).json({ error: 'Não autorizado' });

  if (!db) return res.status(500).json({ error: 'Banco de dados inacessível' });

  const action = req.query.action || req.body.action || 'get-profile';

  try {
    switch (action) {
      case 'get-profile':
        return await handleGetProfile(req, res, auth.uid);
      case 'set-goal':
        return await handleSetGoal(req, res, auth.uid);
      case 'log-meal':
        return await handleLogMeal(req, res, auth.uid);
      case 'get-history':
        return await handleGetHistory(req, res, auth.uid);
      default:
        return res.status(400).json({ error: `Ação inválida: ${action}` });
    }
  } catch (error: any) {
    console.error(`[Nutrition API Error] Action: ${action}`, error);
    return res.status(500).json({ error: error.message || 'Erro inesperado no serviço de nutrição.' });
  }
}

async function handleGetProfile(req: VercelRequest, res: VercelResponse, userId: string) {
  const profileRef = db.collection('user_nutrition_profiles').doc(userId);
  const snap = await profileRef.get();

  if (snap.exists) {
    return res.json(snap.data());
  }

  // Create default nutrition profile if not exists
  let mappedGoal = 'reeducacao';
  
  // Try to read existing objective from general user doc if any
  try {
    const userDocRef = db.collection('users').doc(userId);
    const userSnap = await userDocRef.get();
    if (userSnap.exists) {
      const uData = userSnap.data();
      const obj = uData?.objective || '';
      if (obj === 'emagrecer') mappedGoal = 'emagrecimento';
      else if (obj === 'ganhar_massa') mappedGoal = 'hipertrofia';
      else if (obj === 'definir') mappedGoal = 'performance';
    }
  } catch (err) {
    console.warn('[Nutrition] General user doc fetch warning:', err);
  }

  const newProfile = {
    userId,
    goal: mappedGoal,
    goalUpdatedAt: new Date(0).toISOString(), // Always allow first time updates
    currentStreak: 0,
    bestStreak: 0,
    weeklyConsistency: 100,
    monthlyConsistency: 100,
    lastConsistentDate: null,
    createdAt: new Date().toISOString()
  };

  await profileRef.set(newProfile);
  return res.json(newProfile);
}

async function handleSetGoal(req: VercelRequest, res: VercelResponse, userId: string) {
  const { goal } = req.body;
  if (!goal) return res.status(400).json({ error: 'Nenhum objetivo fornecido.' });

  const validGoals = ['emagrecimento', 'hipertrofia', 'performance', 'manutencao', 'reeducacao'];
  if (!validGoals.includes(goal)) {
    return res.status(400).json({ error: 'Objetivo de dieta inválido.' });
  }

  const profileRef = db.collection('user_nutrition_profiles').doc(userId);
  const snap = await profileRef.get();

  const now = new Date();

  if (snap.exists) {
    const data = snap.data() || {};
    const lastUpdate = data.goalUpdatedAt ? new Date(data.goalUpdatedAt) : new Date(0);
    
    // Rule: max 1 change per week (7 days)
    const sevenDaysInMs = 7 * 24 * 60 * 60 * 1000;
    const diff = now.getTime() - lastUpdate.getTime();

    if (diff < sevenDaysInMs) {
      const daysLeft = Math.ceil((sevenDaysInMs - diff) / (24 * 60 * 60 * 1000));
      return res.status(400).json({ 
        error: `Você atingiu o limite de trocas de objetivo. Aguarde ${daysLeft} dia(s) para alterar seu plano alimentar novamente.` 
      });
    }

    await profileRef.update({
      goal,
      goalUpdatedAt: now.toISOString()
    });

    return res.json({ success: true, goal, goalUpdatedAt: now.toISOString() });
  } else {
    const newProfile = {
      userId,
      goal,
      goalUpdatedAt: now.toISOString(),
      currentStreak: 0,
      bestStreak: 0,
      weeklyConsistency: 100,
      monthlyConsistency: 100,
      lastConsistentDate: null,
      createdAt: now.toISOString()
    };
    await profileRef.set(newProfile);
    return res.json(newProfile);
  }
}

async function handleLogMeal(req: VercelRequest, res: VercelResponse, userId: string) {
  const { photoBase64, description } = req.body;

  if (!photoBase64) {
    return res.status(400).json({ error: 'O upload ou captura de foto da refeição é obrigatório para validação.' });
  }

  // Get current date in Sao Paulo (Brazil) timezone
  const paulDateStr = new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' });

  // 1. Check intervals: at least 1h30 (90 minutes) between any meal logged
  const ninetyMinAgo = new Date(Date.now() - 90 * 60 * 1000);
  const recMealSnap = await db.collection('meal_logs')
    .where('userId', '==', userId)
    .where('createdAt', '>=', ninetyMinAgo.toISOString())
    .limit(1)
    .get();

  if (!recMealSnap.empty) {
    return res.status(400).json({ 
      error: 'Por favor, aguarde pelo menos 1 hora e 30 minutos entre os registros de refeições para garantir a precisão do rastreamento.' 
    });
  }

  // 2. Daily limits: max 6 meal logs per day
  const todayStart = new Date(paulDateStr + 'T00:00:00-03:00').toISOString();
  const todayEnd = new Date(paulDateStr + 'T23:59:59-03:00').toISOString();
  const dayLogsSnap = await db.collection('meal_logs')
    .where('userId', '==', userId)
    .where('createdAt', '>=', todayStart)
    .where('createdAt', '<=', todayEnd)
    .get();

  if (dayLogsSnap.size >= 6) {
    return res.status(400).json({ error: 'Limite de 6 registros de refeição atingido para o dia de hoje. Equilíbrio é tudo!' });
  }

  // 3. Duplicate checks: based on photo hash (SHA-256)
  let imageHash = '';
  if (photoBase64) {
    imageHash = crypto.createHash('sha256').update(photoBase64).digest('hex');
    const dupSnap = await db.collection('meal_logs')
      .where('userId', '==', userId)
      .where('imageHash', '==', imageHash)
      .limit(1)
      .get();

    if (!dupSnap.empty) {
      return res.status(400).json({ error: 'Você já registrou essa refeição hoje! Fotos idênticas ou duplicadas não são aceitas.' });
    }
  }

  // Fetch users goal to feed the AI context
  let userGoal = 'reeducacao';
  const profileRef = db.collection('user_nutrition_profiles').doc(userId);
  const profileSnap = await profileRef.get();
  let nutritionProfile = profileSnap.exists ? profileSnap.data() : null;

  if (nutritionProfile) {
    userGoal = nutritionProfile.goal || 'reeducacao';
  }

  // 4. AIS Call (Gemini-3.5-flash) for nutritional feedback
  const formatObjective: Record<string, string> = {
    emagrecimento: 'Emagrecimento (foco em déficit calórico moderado, fibras, proteínas e densidade de nutrientes)',
    hipertrofia: 'Hipertrofia (foco em superávit ou aporte calórico adequado, alta qualidade de proteínas e carboidratos complexos)',
    performance: 'Performance Desportiva (foco em energia com carboidratos de boa qualidade e recuperação muscular por aminoácidos)',
    manutencao: 'Manutenção de Peso (foco em porções sadias, variedade e distribuição de macronutrientes)',
    reeducacao: 'Reeducação Alimentar (foco em escolhas saudáveis, alimentos naturais, vegetais e redução de ultraprocessados)'
  };

  const currentGoalLabel = formatObjective[userGoal] || userGoal;

  const prompt = `Você é um nutricionista virtual experiente do ecossistema fitness INVICTUS.
Analise a imagem de comida enviada pelo usuário sob a ótica do seu objetivo nutricional pessoal: **${currentGoalLabel}**.

REGRAS DE VALIDAÇÃO E SEGURANÇA (EVITAR BURLAS):
1. A imagem DEVE ser de comida real, preparada ou pronta para consumo (como um prato de comida, fruta, iogurte, lanche, shake, salada).
2. Se a imagem for uma tela de monitor/celular/computador/TV, um objeto aleatório, uma pessoa, um animal, um ambiente sem comida saudável visível, uma embalagem fechada (caixa, pote, saco plástico sem comida exposta), ou uma imagem totalmente preta/branca, você DEVE REJEITAR o registro de imediato.
3. Se rejeitado por fraude/imagem inadequada, configure:
   - "adherenceScore" como 0
   - "confidenceLevel" como "low"
   - "feedbackText" como "Não foi possível identificar comida real na foto enviada. Por favor, tire uma foto nítida e direta da sua refeição (no prato/copo/recipiente) para que a IA possa analisar e manter sua consistência diária."
   - "detectedFoods" como []
   - "estimatedCalories": 0, "estimatedProteinGrams": 0, "estimatedCarbsGrams": 0, "estimatedFatGrams": 0

Se for uma foto válida de alimentos, seu feedback deve ser estritamente educativo, amigável e amparador.
No seu feedback técnico de alimentos válidos:
1. Identifique os prováveis alimentos visíveis na foto ou descritos no texto.
2. Estime as porções aproximadas de cada um.
3. Calcule uma estimativa razoável de Calorias Totais (kcal) e Macronutrientes (Proteínas, Carboidratos e Gorduras em gramas).
4. Classifique alimentos detectados de forma neutra em categorias (categorias válidas ex: complete meal, protein present, fiber present, vegetables, fast-food, desserts, healthy fats).
5. Atribua um score de adesão de 0 a 100 baseado na adequação ao objetivo do usuário.
6. Defina um nível de confiança da sua análise visual (low, medium ou high).

Forneça a saída em formato JSON estrito, sem tags markdown adicionais (ex: \`\`\`json ou semelhantes), contendo as chaves exatas descritas abaixo:
{
  "detectedFoods": ["Arroz integral", "Peito de frango", "Salada de alface e tomate"],
  "portionEstimate": "150g arroz, 120g frango grelhado, porção livre de salada",
  "estimatedCalories": 420,
  "estimatedProteinGrams": 38,
  "estimatedCarbsGrams": 40,
  "estimatedFatGrams": 8,
  "confidenceLevel": "high",
  "detectedCategories": ["complete meal", "protein present", "vegetables"],
  "adherenceScore": 95,
  "feedbackText": "Excelente escolha! Um prato muito bem equilibrado e alinhado ao seu objetivo de Hipertrofia..."
}`;

  let contents: any;
  if (photoBase64) {
    contents = {
      parts: [
        { inlineData: { mimeType: 'image/jpeg', data: photoBase64 } },
        { text: description ? `O usuário descreve esta refeição como: "${description}".\n\n${prompt}` : prompt }
      ]
    };
  } else {
    contents = {
      parts: [
        { text: `O usuário descreve sua refeição manualmente: "${description}".\n\n${prompt}` }
      ]
    };
  }

  let aiResponseText = '';
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3.5-flash',
      contents,
    });
    aiResponseText = response.text || '';
  } catch (err: any) {
    console.error('[Gemini Call Failed] Falling back to manual heuristics', err);
    // Safe heuristic fallback in case the API limit or key issue arises
    aiResponseText = JSON.stringify({
      detectedFoods: description ? [description] : ['Refeição Logada'],
      portionEstimate: description || 'Porção não descrita',
      estimatedCalories: 350,
      estimatedProteinGrams: 20,
      estimatedCarbsGrams: 40,
      estimatedFatGrams: 10,
      confidenceLevel: 'medium',
      detectedCategories: ['protein present'],
      adherenceScore: 75,
      feedbackText: 'Ótimo registro alimentar! Sua refeição foi contabilizada para o seu streak de consistência.'
    });
  }

  // Clean brackets or tags if model outputs them
  let cleanJson = aiResponseText.trim();
  if (cleanJson.startsWith('```')) {
    cleanJson = cleanJson.replace(/^```json\s*/i, '').replace(/```$/, '').trim();
  }

  let parsed: any;
  try {
    parsed = JSON.parse(cleanJson);
  } catch (err) {
    console.warn('[Nutrition JSON Parse failed] Output text:', aiResponseText);
    parsed = {
      detectedFoods: description ? [description] : ['Refeição Estimada'],
      portionEstimate: 'Informação descrita',
      estimatedCalories: 380,
      estimatedProteinGrams: 22,
      estimatedCarbsGrams: 45,
      estimatedFatGrams: 12,
      confidenceLevel: 'medium',
      detectedCategories: [],
      adherenceScore: 75,
      feedbackText: 'Obrigado por registrar! Análise gerada pela nossa IA de consistência.'
    };
  }

  // 5. Create the MealLog doc
  const mealId = db.collection('meal_logs').doc().id;
  const createdAtStr = new Date().toISOString();
  
  const mealLogDoc = {
    id: mealId,
    userId,
    imageUrl: photoBase64 ? `data:image/jpeg;base64,${photoBase64}` : null,
    createdAt: createdAtStr,
    detectedFoods: parsed.detectedFoods || [],
    portionEstimate: parsed.portionEstimate || 'Não estimado',
    estimatedCalories: Number(parsed.estimatedCalories) || 0,
    estimatedProteinGrams: Number(parsed.estimatedProteinGrams) || 0,
    estimatedCarbsGrams: Number(parsed.estimatedCarbsGrams) || 0,
    estimatedFatGrams: Number(parsed.estimatedFatGrams) || 0,
    confidenceLevel: parsed.confidenceLevel || 'medium',
    detectedCategories: parsed.detectedCategories || [],
    adherenceScore: Number(parsed.adherenceScore) || 70,
    feedbackText: parsed.feedbackText || 'Refeição registrada com sucesso!',
    imageHash,
    isDuplicate: false,
    fraudFlags: [],
    isEligibleForStreak: (parsed.confidenceLevel !== 'low')
  };

  await db.collection('meal_logs').doc(mealId).set(mealLogDoc);

  // 6. Recalculate today's summaries & streaks
  // Gather all of today's meals logged by user
  const todayMealsSnap = await db.collection('meal_logs')
    .where('userId', '==', userId)
    .where('createdAt', '>=', todayStart)
    .where('createdAt', '<=', todayEnd)
    .get();

  const todayMeals: any[] = [];
  todayMealsSnap.forEach(d => todayMeals.push(d.data()));
  // Ensure the current newly logged meal is counted
  if (!todayMeals.some(m => m.id === mealId)) {
    todayMeals.push(mealLogDoc);
  }

  const validMealsCount = todayMeals.length;
  const totalAdherence = todayMeals.reduce((acc, current) => acc + (current.adherenceScore || 0), 0);
  const averageAdherence = validMealsCount > 0 ? Math.round(totalAdherence / validMealsCount) : 0;

  // Streak conditions: at least 2 valid meals, average adherence >= 60%
  const todayStreakMaintained = (validMealsCount >= 2 && averageAdherence >= 60);

  // Write/Update DailyNutritionSummary
  const summaryId = `${userId}_${paulDateStr}`;
  const dailySummary = {
    userId,
    date: paulDateStr,
    validMealsCount,
    averageAdherence,
    streakMaintained: todayStreakMaintained,
    consistencyScore: averageAdherence,
    updatedAt: new Date().toISOString()
  };
  await db.collection('daily_nutrition_summaries').doc(summaryId).set(dailySummary);

  // 7. Re-evaluate overall streaks
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  const yesterdayPaulStr = yesterday.toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' });

  // Let's load the nutrition profile to update streak
  if (!nutritionProfile) {
    nutritionProfile = {
      userId,
      goal: userGoal,
      goalUpdatedAt: new Date(0).toISOString(),
      currentStreak: 0,
      bestStreak: 0,
      weeklyConsistency: 100,
      monthlyConsistency: 100,
      lastConsistentDate: null,
      createdAt: new Date().toISOString()
    };
  }

  let finalCurrentStreak = nutritionProfile.currentStreak || 0;
  let finalBestStreak = nutritionProfile.bestStreak || 0;
  let lastConsistentDate = nutritionProfile.lastConsistentDate;

  if (todayStreakMaintained) {
    if (lastConsistentDate === paulDateStr) {
      // Already marked as consistent today, streak is updated already
    } else if (lastConsistentDate === yesterdayPaulStr) {
      // Streak continues consecutively
      finalCurrentStreak += 1;
      lastConsistentDate = paulDateStr;
    } else {
      // Streak broken or starting fresh
      finalCurrentStreak = 1;
      lastConsistentDate = paulDateStr;
    }
    finalBestStreak = Math.max(finalBestStreak, finalCurrentStreak);
  } else {
    // Today meets less than 2 meals or < 60% adherence yet
    // If last consistent was yesterday, we don't break streak *yet* in real-time UI because they might log their second meal later today!
    // Wait, if last consistent was before yesterday (2+ days ago), the streak has officially expired.
    if (lastConsistentDate && lastConsistentDate !== yesterdayPaulStr && lastConsistentDate !== paulDateStr) {
      finalCurrentStreak = 0;
    }
  }

  // Calculate consistency percentage (last 7 days and 30 days)
  // Fetch summaries for the last 30 calendar days
  const thirtyDaysAgo = new Date();
  thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
  const sumsSnap = await db.collection('daily_nutrition_summaries')
    .where('userId', '==', userId)
    .where('date', '>=', thirtyDaysAgo.toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' }))
    .get();

  const activeSumDocs: any[] = [];
  sumsSnap.forEach(d => activeSumDocs.push(d.data()));

  // Ensure current dailySummary is analyzed
  if (!activeSumDocs.some(s => s.date === paulDateStr)) {
    activeSumDocs.push(dailySummary);
  }

  // Calculate 7 days
  const sevenDaysAgoPaulStr = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' });
  const consistent7Days = activeSumDocs.filter(s => s.date >= sevenDaysAgoPaulStr && s.streakMaintained === true).length;
  const weeklyConsistency = Math.round((consistent7Days / 7) * 100);

  // Calculate 30 days
  const consistent30Days = activeSumDocs.filter(s => s.streakMaintained === true).length;
  const monthlyConsistency = Math.round((consistent30Days / 30) * 100);

  // Complete profile updates
  const profileUpdates = {
    currentStreak: finalCurrentStreak,
    bestStreak: finalBestStreak,
    lastConsistentDate,
    weeklyConsistency,
    monthlyConsistency,
    updatedAt: new Date().toISOString()
  };

  await db.collection('user_nutrition_profiles').doc(userId).set({
    ...nutritionProfile,
    ...profileUpdates
  });

  // Check if any badges/nutrition achievements are unlocked
  // Badges can include:
  // - "First Step": Log your first meal
  // - "Consistência de Ouro": Keep a 7-day solid nutrition streak
  // - "Foco Total": Keep a 15-day solid nutrition streak
  // - "Mestre Nutricional": Reach 30-day streak
  const achievementsList = [];
  if (finalCurrentStreak >= 7) achievementsList.push('nutrition_streak_7');
  if (finalCurrentStreak >= 15) achievementsList.push('nutrition_streak_15');
  if (finalCurrentStreak >= 30) achievementsList.push('nutrition_streak_30');

  // Return the newly created MealLog and summary state
  return res.json({
    mealLog: mealLogDoc,
    nutritionProfile: {
      ...nutritionProfile,
      ...profileUpdates
    },
    todaySummary: dailySummary,
    unlockedAchievements: achievementsList
  });
}

async function handleGetHistory(req: VercelRequest, res: VercelResponse, userId: string) {
  // Return daily summaries and last 10 meal logs for rendering
  const mealLogsSnap = await db.collection('meal_logs')
    .where('userId', '==', userId)
    .orderBy('createdAt', 'desc')
    .limit(15)
    .get();

  const meals: any[] = [];
  mealLogsSnap.forEach(doc => {
    // Hide massive image payload for lists if required to maintain responsiveness, or keep it.
    // For this applet, keeping it is optimal for instant rendering!
    meals.push(doc.data());
  });

  const thirtyDaysAgo = new Date();
  thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
  const sumsSnap = await db.collection('daily_nutrition_summaries')
    .where('userId', '==', userId)
    .where('date', '>=', thirtyDaysAgo.toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' }))
    .get();

  const summaries: any[] = [];
  sumsSnap.forEach(doc => summaries.push(doc.data()));

  return res.json({
    meals,
    summaries: summaries.sort((a, b) => b.date.localeCompare(a.date))
  });
}
