import dotenv from 'dotenv';
dotenv.config({ override: true });
import express from 'express';
import { VercelRequest, VercelResponse } from '@vercel/node';
import path from 'path';

// Import all handlers from _handlers
// Note: We use relative imports. In Vercel, these will be bundled.
import healthHandler from './_handlers/health';
import profileHandler from './_handlers/profile';
import rankingHandler from './_handlers/ranking';
import shareHandler from './_handlers/share';
import shareImageHandler from './_handlers/share-image';
import gymsHandler from './_handlers/gyms';
import gymsJoinHandler from './_handlers/gyms_join';
import gymsCheckinHandler from './_handlers/gyms_checkin';
import gymsPhotoHandler from './_handlers/gyms_photo';
import runningHandler from './_handlers/running';
import validateActivityHandler from './_handlers/validate-activity';
import validatePresenceHandler from './_handlers/validate-presence';
import eliteHandler from './_handlers/elite';
import whatsappHandler from './_handlers/whatsapp';
import stravaHandler from './_handlers/strava';
import migrateResetHandler from './_handlers/migrate-reset';
import envCheckHandler from './_handlers/env-check';
import mercadopagoHandler from './_handlers/mercadopago';
import nutritionHandler from './_handlers/nutrition';
import walletRedeemHandler from './_handlers/wallet-redeem';
import adminHandler from './_handlers/admin';
import denounceHandler from './_handlers/denounce';
import paymentsCreateCheckoutHandler from './_handlers/payments-create-checkout';
import paymentsWebhookHandler from './_handlers/payments-webhook';
import paymentsStatusHandler from './_handlers/payments-status';
import paymentsConfigHandler from './_handlers/payments-config';
import paymentsDebugMercadoPagoHandler from './_handlers/payments-debug-mercado-pago';
import privateChallengesHandler from './_handlers/private-challenges';
import pagarmeHandler from './_handlers/pagarme';

const router = express.Router();
console.log('[API Router] Initializing routes...');

// Global API CORS and headers
router.use((req, res, next) => {
  const origin = req.headers.origin;
  if (origin) {
    res.setHeader('Access-Control-Allow-Origin', origin);
    res.setHeader('Access-Control-Allow-Credentials', 'true');
  } else {
    res.setHeader('Access-Control-Allow-Origin', '*');
  }
  res.setHeader('Access-Control-Allow-Methods', 'GET,POST,PUT,DELETE,OPTIONS,PATCH');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization, X-Requested-With');
  
  if (req.method === 'OPTIONS') {
    return res.status(200).end();
  }
  next();
});

// Helper to wrap Vercel handlers for Express with error handling
const wrap = (handler: any) => async (req: any, res: any) => {
  try {
    await handler(req, res);
  } catch (err: any) {
    console.error(`[API Error] Error in handler:`, err);
    if (!res.headersSent) {
      res.status(500).json({ 
        error: err.message || 'Erro interno no servidor.',
        stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
      });
    }
  }
};

// 1. Routes (paths are relative to /api mount point)
router.all('/health', wrap(healthHandler));
router.all('/profile', wrap(profileHandler));
router.all('/ranking', wrap(rankingHandler));
router.all('/share', wrap(shareHandler));
router.all('/share-image', wrap(shareImageHandler));
router.all('/gyms', wrap(gymsHandler));
router.all('/gyms/join', wrap(gymsJoinHandler));
router.all('/gyms/checkin', wrap(gymsCheckinHandler));
router.all('/gyms/photo', wrap(gymsPhotoHandler));
router.all('/running', wrap(runningHandler));
router.all('/validate-activity', wrap(validateActivityHandler));
router.all('/validate-presence', wrap(validatePresenceHandler));
router.all('/elite', wrap(eliteHandler));
router.all('/strava', wrap(stravaHandler));
router.all('/whatsapp/send', wrap(whatsappHandler));
router.all('/env-check', wrap(envCheckHandler));
router.all('/mercadopago', wrap(mercadopagoHandler));
router.all('/payments/create-checkout', wrap(paymentsCreateCheckoutHandler));
router.all('/payments/config', wrap(paymentsConfigHandler));
router.all('/payments/debug-mercado-pago', wrap(paymentsDebugMercadoPagoHandler));
router.all('/payments/webhook', wrap(paymentsWebhookHandler));
router.all('/payments/pagarme', wrap(pagarmeHandler));
router.all('/payments/status/:orderId', wrap(paymentsStatusHandler));
router.all('/payments/status', wrap(paymentsStatusHandler));
router.all('/nutrition', wrap(nutritionHandler));
router.all('/wallet/redeem', wrap(walletRedeemHandler));
router.all('/migrate-reset', wrap(migrateResetHandler));
router.all('/admin', wrap(adminHandler));
router.all('/denounce', wrap(denounceHandler));
router.all('/private-challenges', wrap(privateChallengesHandler));

// Support for the /share/:id custom route
router.get('/share/:id', (req, res) => {
  req.query.id = req.params.id;
  return shareHandler(req as any, res as any);
});

// 2. The Unified Endpoint
router.all('/app', async (req, res) => {
  const action = (req.query.action || req.body.action) as string;
  
  switch (action) {
    case 'health': return healthHandler(req as any, res as any);
    case 'profile': return profileHandler(req as any, res as any);
    case 'ranking': return rankingHandler(req as any, res as any);
    case 'gyms': return gymsHandler(req as any, res as any);
    case 'gyms-join': return gymsJoinHandler(req as any, res as any);
    case 'gyms-checkin': return gymsCheckinHandler(req as any, res as any);
    case 'validate-activity': return validateActivityHandler(req as any, res as any);
    case 'validate-presence': return validatePresenceHandler(req as any, res as any);
    case 'nutrition': return nutritionHandler(req as any, res as any);
    case 'strava': return stravaHandler(req as any, res as any);
    case 'whatsapp-send': return whatsappHandler(req as any, res as any);
    case 'wallet-redeem': return walletRedeemHandler(req as any, res as any);
    case 'payments-create-checkout': return paymentsCreateCheckoutHandler(req as any, res as any);
    case 'payments-config': return paymentsConfigHandler(req as any, res as any);
    case 'payments-debug-mercado-pago': return paymentsDebugMercadoPagoHandler(req as any, res as any);
    case 'payments-webhook': return paymentsWebhookHandler(req as any, res as any);
    case 'pagarme': return pagarmeHandler(req as any, res as any);
    case 'payments-status': return paymentsStatusHandler(req as any, res as any);
    case 'migrate-reset': return migrateResetHandler(req as any, res as any);
    case 'admin': return adminHandler(req as any, res as any);
    case 'private-challenges': return privateChallengesHandler(req as any, res as any);
    default: 
      return res.status(400).json({ 
        error: 'Ação inválida ou não fornecida.',
        tip: 'Use /api/app?action=profile ou os endpoints específicos.' 
      });
  }
});

export default router;
