import { VercelRequest, VercelResponse } from '@vercel/node';
import { db, cors, verifyAuth } from '../_lib/common';
import { MercadoPagoConfig, Preference } from 'mercadopago';
import { logPaymentAudit } from '../_lib/payments-service';

const PLANS: Record<string, { name: string; price: number }> = {
  'invictus_monthly': {
    name: 'Plano Invictus Mensal',
    price: 1.00
  },
  'invictus_annual': {
    name: 'Plano Invictus Anual',
    price: 1.00
  },
  'invictus_open': {
    name: 'Invictus Open',
    price: 9.90
  },
  'invictus_performance': {
    name: 'Invictus Performance',
    price: 29.90
  }
};

export default async function handler(req: VercelRequest, res: VercelResponse) {
  if (cors(req, res)) return;

  if (req.method !== 'POST') {
    return res.status(455).json({ error: 'Método não permitido.' });
  }

  // 1. Verify Authentication
  const authUser = await verifyAuth(req);
  if (!authUser) {
    return res.status(401).json({ error: 'Sessão expira ou inválida. Conecte-se novamente.' });
  }

  const { planId = 'invictus_monthly' } = req.body;
  const plan = PLANS[planId];
  if (!plan) {
    return res.status(400).json({ error: 'Plano selecionado é inválido.' });
  }

  const possibleVarNames = [
    'TOKEN_DE_ACESSO_AO_MERCADO_PAGO',
    'MERCADO_PAGO_ACESS_TOKEN',
    'MERCADO_PAGO_ACCESS_TOKEN',
    'MP_ACCESS_TOKEN',
    'MERCADOPAGO_ACCESS_TOKEN',
    'MERCADO_PAGO_TOKEN',
    'MP_TOKEN'
  ];

  let selectedVarName = 'MERCADO_PAGO_ACCESS_TOKEN';
  let accessToken = '';

  // 1. Try to find a production token starting with 'APP_USR-'
  for (const varName of possibleVarNames) {
    const val = (process.env[varName] || '').trim();
    if (val && val.startsWith('APP_USR-')) {
      accessToken = val;
      selectedVarName = varName;
      break;
    }
  }

  // 2. Fallback to any valid token if no production token was found
  if (!accessToken) {
    for (const varName of possibleVarNames) {
      const val = (process.env[varName] || '').trim();
      if (val && !val.toLowerCase().includes('placeholder') && !val.toLowerCase().includes('seu_token') && val.length >= 15) {
        accessToken = val;
        selectedVarName = varName;
        break;
      }
    }
  }

  if (!accessToken) {
    accessToken = (process.env.MERCADO_PAGO_ACCESS_TOKEN || '').trim();
  }

  const finalPrice = plan.price;

  try {
    const now = new Date();

    // 2. Duplicity Rule 1: check if user already has an approved/active entitlement
    const entitlementsSnap = await db.collection('user_entitlements')
      .where('userId', '==', authUser.uid)
      .where('planId', '==', planId)
      .where('status', '==', 'active')
      .get();
    
    let hasActiveEntitlement = false;
    for (const doc of entitlementsSnap.docs) {
      const data = doc.data();
      const endsAt = data.endsAt ? new Date(data.endsAt) : null;
      if (!endsAt || endsAt > now) {
        hasActiveEntitlement = true;
      }
    }

    if (hasActiveEntitlement) {
      return res.status(400).json({ 
        error: 'Você já possui uma assinatura ativa para este plano no momento.',
        code: 'ALREADY_ACTIVE'
      });
    }

    // 3. Duplicity Rule 2: Cancel previous pending orders and always generate a fresh experience to avoid caching stale/blocked checkout URLs
    const pendingOrdersSnap = await db.collection('payment_orders')
      .where('userId', '==', authUser.uid)
      .where('planId', '==', planId)
      .where('status', '==', 'pending')
      .get();

    if (!pendingOrdersSnap.empty) {
      console.log(`[Payments] Cancelling preceding pending orders for user ${authUser.uid} to create a fresh one.`);
      const batch = db.batch();
      for (const pendingDoc of pendingOrdersSnap.docs) {
        batch.update(pendingDoc.ref, {
          status: 'cancelled',
          updatedAt: now.toISOString()
        });
      }
      await batch.commit();
    }

    // 4. Create internal order reference
    const orderId = db.collection('payment_orders').doc().id;

    // 5. Initialize Mercado Pago client
    const client = new MercadoPagoConfig({ accessToken });
    const preference = new Preference(client);

    // Resolve Base URL for callbacks: prioritize official domain over temporary run.app or localhost
    let baseUrl = 'https://www.desafiosemdesculpa.com.br';
    
    // Attempt automatic detection of official domain from environment
    const publicUrlCandidates = [
      process.env.MP_SUCCESS_URL,
      process.env.VITE_APP_URL,
      process.env.VITE_API_URL
    ];
    
    let foundOfficialDomain = false;
    for (const candidate of publicUrlCandidates) {
      if (candidate) {
        try {
          const parsed = new URL(candidate);
          const hostname = parsed.hostname.toLowerCase();
          if (hostname.includes('desafiosemdesculpa.com.br')) {
            baseUrl = parsed.origin;
            foundOfficialDomain = true;
            break;
          }
        } catch (e) {}
      }
    }

    // Default back to request host if we are in local development testing and no official domain is present
    if (!foundOfficialDomain) {
      const forwardedHost = req.headers['x-forwarded-host'] as string | undefined;
      const host = forwardedHost || req.headers.host || '';
      if (host && !host.includes('localhost') && !host.includes('127.0.0.1')) {
        baseUrl = `https://${host}`;
      }
    }
    
    if (baseUrl.endsWith('/')) {
      baseUrl = baseUrl.slice(0, -1);
    }

    // Callback backURLs that point to the secure /pagamento/sucesso landing screen as requested
    const backUrls = {
      success: `${baseUrl}/pagamento/sucesso?payment=success&orderId=${orderId}`,
      failure: `${baseUrl}/settings?payment=failure&orderId=${orderId}`,
      pending: `${baseUrl}/pagamento/sucesso?payment=pending&orderId=${orderId}`
    };

    const notificationUrl = `${baseUrl}/api/payments/webhook`;

    // Ensure payer email is present
    let userEmail = authUser.email;
    if (!userEmail) {
      try {
        const userDoc = await db.collection('users').doc(authUser.uid).get();
        if (userDoc.exists) {
          userEmail = userDoc.data()?.email;
        }
      } catch (err) {
        console.warn('[Payments] Could not query user email from users collection:', err);
      }
    }
    if (!userEmail) {
      userEmail = 'samuelfsc89@gmail.com'; // Use the logged in diagnostic user as resilient fallback
    }

    const body: any = {
      items: [
        {
          id: planId,
          title: plan.name,
          unit_price: finalPrice,
          quantity: 1,
          currency_id: 'BRL'
        }
      ],
      payer: {
        email: userEmail
      },
      payment_methods: {
        excluded_payment_types: [
          { id: "ticket" },       // Exclude Boleto (Ticket)
          { id: "debit_card" },   // Exclude Debit Cards
          { id: "prepaid_card" }, // Exclude Prepaid Cards
          { id: "atm" }           // Exclude ATM payments
          // We DO NOT exclude bank_transfer (which Pix belongs to) or credit_card
        ],
        installments: 12          // Support up to 12 installments for credit card
      },
      binary_mode: false,         // Do not block Pix or Credit Card with strict binary mode
      external_reference: orderId,
      back_urls: backUrls,
      auto_return: 'approved' as const,
      metadata: {
        userId: authUser.uid,
        orderId: orderId,
        planId: planId
      }
    };

    // Mercado Pago rejects webhook notification URLs on localhost or non-public domains.
    // So we only include notification_url if it's a valid public url.
    if (!notificationUrl.includes('localhost') && !notificationUrl.includes('127.0.0.1') && notificationUrl.startsWith('https://')) {
      body.notification_url = notificationUrl;
      console.log('[Payments] Setting notification_url:', notificationUrl);
    } else {
      console.warn('[Payments] Skipping notification_url in development/localhost mode to avoid Mercado Pago preference errors:', notificationUrl);
    }

    let result: any = null;
    let checkoutUrl = '';

    const isProduction = process.env.NODE_ENV === 'production' || process.env.VERCEL_ENV === 'production' || process.env.VERCEL === '1';
    const tokenPrefix = accessToken ? accessToken.substring(0, 15) : '';
    const tokenLength = accessToken ? accessToken.length : 0;

    const diagnosticData: any = {
      rota_chamada: '/api/payments/create-checkout',
      node_env: process.env.NODE_ENV || 'undefined',
      vercel_env: process.env.VERCEL_ENV || 'undefined',
      token_variable_name_used: selectedVarName,
      token_prefix: tokenPrefix,
      token_length: tokenLength,
      is_production_detected: isProduction,
      init_point: '',
      sandbox_init_point: '',
      checkout_url_final: ''
    };

    // Strict validation of the Mercado Pago Access Token
    if (!accessToken || accessToken.trim() === '') {
      console.error('[Payments] Erro de configuração: Access Token do Mercado Pago ausente.', { diagnosticData });
      return res.status(400).json({ error: 'Configuração do Mercado Pago inválida: Access Token ausente.', ...diagnosticData });
    }

    if (accessToken.toLowerCase().includes('placeholder') || accessToken.toLowerCase().includes('seu_token') || accessToken.length < 15) {
      console.error('[Payments] Erro de validação: Token inválido ou vazio detectado.', { tokenStart: accessToken.substring(0, 10), diagnosticData });
      return res.status(400).json({ error: 'Checkout rejeitado. Credenciais do Mercado Pago inválidas ou de placeholder detectadas.', ...diagnosticData });
    }

    if (isProduction && accessToken.startsWith('TEST-')) {
      console.error('[Payments] Bloqueio imediato de segurança: Credencial de teste (TEST-) rejeitada em produção.', { diagnosticData });
      return res.status(400).json({ error: 'Checkout configurado em sandbox. Credenciais TEST- negadas em produção.', ...diagnosticData });
    }

    if (isProduction && !accessToken.startsWith('APP_USR-')) {
      console.error('[Payments] Bloqueio imediato de segurança: Apenas credenciais APP_USR- são permitidas em produção.', { diagnosticData });
      return res.status(400).json({ error: 'Checkout configurado de forma insegura. Apenas credenciais de produção (APP_USR-) são válidas.', ...diagnosticData });
    }

    const hasValidTokenFormat = accessToken.startsWith('APP_USR-') || (!isProduction && accessToken.startsWith('TEST-'));
    if (!hasValidTokenFormat) {
      console.error('[Payments] Formato de token não autorizado:', { tokenStart: accessToken.substring(0, 10), diagnosticData });
      return res.status(400).json({ error: 'Formato do token do Mercado Pago inválido ou não autorizado.', ...diagnosticData });
    }

    try {
      console.log('[Payments] Creating MP preference for orderId:', orderId);
      
      // Use Promise.race to enforce a 3.5s timeout so slow Mercado Pago calls don't block the UI
      const apiCall = preference.create({ body });
      
      // Register a catch handler directly on the original promise to prevent unhandled rejection crashes if it fails after timeout
      apiCall.catch((err) => {
        console.warn('[Payments] Mercado Pago background preference creation rejected safely:', err.message || err);
      });

      const timeoutCall = new Promise<never>((_, reject) => 
        setTimeout(() => reject(new Error('Gateway timeout: Mercado Pago demorou mais de 3.5 segundos para responder.')), 3500)
      );

      result = await Promise.race([apiCall, timeoutCall]);
      const isSandboxAux = accessToken.startsWith('TEST-');
      const realStatusIsSandbox = isSandboxAux || (result.init_point && result.init_point.toLowerCase().includes('sandbox.mercadopago'));
      const detectedAmbiente = realStatusIsSandbox ? 'sandbox' : 'production';
      
      // Exclusively use init_point
      checkoutUrl = result.init_point || '';
      
      // Fill dynamic diagnostic fields
      diagnosticData.init_point = result.init_point || '';
      diagnosticData.sandbox_init_point = result.sandbox_init_point || '';
      diagnosticData.checkout_url_final = checkoutUrl;

      // If prefix says APP_USR but Mercado Pago returns a sandbox URL, show the full result content in console
      if (accessToken.startsWith('APP_USR-') && checkoutUrl.toLowerCase().includes('sandbox.mercadopago')) {
        console.error('[Payments Diagnostics ERROR] TOKEN PREFIX IS APP_USR, BUT MERCADO PAGO RETURNED SANDBOX URL!', {
          token_prefix: accessToken.substring(0, 15),
          token_length: accessToken.length,
          full_mp_preference_response: result,
          request_body_sent: body
        });
      }

      // Explicit logging for diagnostics
      console.log('[Payments] Diagnóstico de Criação de Preferência:', diagnosticData);

      // Strict check: Any sandbox checkout domain must be blocked
      if (checkoutUrl.toLowerCase().includes('sandbox.mercadopago')) {
        console.error('[Payments] ERRO CRÍTICO DE SEGURANÇA: URL de checkout em sandbox de forma inesperada!', { checkoutUrl });
        return res.status(500).json({
          error: 'Checkout configurado em sandbox. Verifique credenciais e init_point.',
          ...diagnosticData,
          preference_id: result?.id || '',
          full_mp_response_on_mismatch: accessToken.startsWith('APP_USR-') ? result : undefined
        });
      }

      console.log('[Payments] Mercado Pago API Preference Creation [SUCCESS]:', {
        preferenceId: result?.id,
        init_point: result?.init_point,
        collector_id: result?.collector_id,
        payment_methods_sent: body.payment_methods,
        selected_checkout_url: checkoutUrl,
        is_sandbox: realStatusIsSandbox
      });

      // Save diagnostics to database
      await db.collection('utils').doc('mp_debug').set({
        environment: detectedAmbiente,
        hasAccessToken: true,
        hasPublicKey: !!process.env.MERCADO_PAGO_PUBLIC_KEY,
        lastPreferenceId: result?.id || null,
        lastPayload: body,
        selectedInitPointType: 'init_point',
        selectedInitPoint: checkoutUrl,
        collector_id: result?.collector_id || null,
        lastDiagnostics: diagnosticData,
        updatedAt: new Date().toISOString()
      }, { merge: true });

    } catch (err: any) {
      console.error('[Payments] Mercado Pago API preference creation failed:', err);
      const isSandbox = accessToken.startsWith('TEST-');
      await db.collection('utils').doc('mp_debug').set({
        environment: isSandbox ? 'sandbox' : 'production',
        hasAccessToken: true,
        hasPublicKey: !!process.env.MERCADO_PAGO_PUBLIC_KEY,
        lastPreferenceId: null,
        lastPayload: body,
        selectedInitPointType: 'init_point',
        selectedInitPoint: null,
        collector_id: null,
        lastError: {
          message: err.message,
          status: err.status,
          response: err.response?.data || err.data || null
        },
        updatedAt: new Date().toISOString()
      }, { merge: true });
      
      return res.status(500).json({
        error: 'Erro na criação do checkout do Mercado Pago. Por favor, verifique as credenciais.'
      });
    }

    if (!checkoutUrl) {
      throw new Error('Nenhum checkout url foi gerado pelo Mercado Pago.');
    }

    // 6. Save internal order record to database
    const orderDoc = {
      orderId,
      userId: authUser.uid,
      planId,
      amount: finalPrice,
      currency: 'BRL',
      status: 'pending',
      provider: 'mercado_pago',
      preferenceId: result.id || '',
      paymentId: '',
      externalReference: orderId,
      checkoutUrl,
      createdAt: now.toISOString(),
      updatedAt: now.toISOString(),
      rawStatus: 'pending',
      riskFlags: []
    };

    await db.collection('payment_orders').doc(orderId).set(orderDoc);

    // Save audit log
    await logPaymentAudit({
      userId: authUser.uid,
      orderId,
      paymentId: result.id || '',
      previousStatus: 'none',
      newStatus: 'pending',
      eventSource: 'checkout_created',
      action: 'checkout_created',
      reason: `Checkout do Mercado Pago criado com sucesso para o plano ${planId}.`
    });

    return res.status(200).json({
      success: true,
      orderId,
      checkoutUrl,
      preferenceId: result.id,
      
      // Mandatory diagnostic log properties requested by user of the actual API output
      ...diagnosticData,
      preference_id: result.id || '',
      full_mp_response_on_mismatch: (accessToken.startsWith('APP_USR-') && checkoutUrl.toLowerCase().includes('sandbox.mercadopago')) ? result : undefined
    });

  } catch (error: any) {
    console.error('[Payments Create Checkout Error] Full error details:', {
      message: error.message,
      stack: error.stack,
      name: error.name,
      response: error.response,
      status: error.status,
      cause: error.cause,
      data: error.response?.data || error.data
    });
    return res.status(500).json({ 
      error: 'Não foi possível iniciar o pagamento agora. Tente novamente em alguns instantes.',
      details: error.message 
    });
  }
}
